        const pr = st.t === 'probe' ? `<div class="l5-probes">${st.probes.map((p, j) => `<button type="button" class="l5-probe ${v.seen.includes(j) ? 'seen' : ''}" data-l5-probe="${j}" ${a} ${dis}><b>🔍 ตรวจ${esc(p[0])}</b>${v.seen.includes(j) ? `<span>${esc(p[1])}</span>` : '<span class="muted">กดเพื่อดูผล</span>'}</button>`).join('')}</div><p class="l5-sub">ตรวจไปแล้ว ${v.seen.length} ส่วน · สาเหตุคือข้อใด</p>` : '';
